description:
Write `runTests(tests)` where `tests` is an array of `{ name, fn }`. It runs every test, one after another, and returns a promise of a report:

```javascript
{ passed: 2, failed: 1, results: [ { name: "adds", ok: true }, { name: "divides", ok: false, error: "expected 2, got 3" }, ... ] }
```

- `fn` may be synchronous or `async`; a test fails when it throws or its promise rejects, and the error's `message` (or the value itself turned into a string, if it is not an `Error`) goes in `error`;
- a test that takes longer than 200 ms fails with the error `"timed out"`, and the runner moves on;
- one failing test never stops the others; results keep the order of the tests.

starter.solution.js:
async function runTests(tests) {
  const results = [];
  for (const t of tests) {
    await t.fn();
    results.push({ name: t.name, ok: true });
  }
  return { passed: results.length, failed: 0, results };
}

solution.solution.js:
async function runTests(tests) {
  const results = [];
  for (const t of tests) {
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error("timed out")), 200);
    });
    try {
      await Promise.race([Promise.resolve().then(() => t.fn()), timeout]);
      results.push({ name: t.name, ok: true });
    } catch (e) {
      results.push({ name: t.name, ok: false, error: e instanceof Error ? e.message : String(e) });
    } finally {
      clearTimeout(timer);
    }
  }
  const passed = results.filter(r => r.ok).length;
  return { passed, failed: results.length - passed, results };
}

unitTests:
test("passes and failures are counted", async () => {
  const report = await runTests([
    { name: "a", fn: () => {} },
    { name: "b", fn: () => { throw new Error("boom"); } },
    { name: "c", fn: async () => {} },
  ]);
  checkEq([report.passed, report.failed], [2, 1]);
  checkEq(report.results.map(r => r.name), ["a", "b", "c"]);
  checkEq(report.results[1], { name: "b", ok: false, error: "boom" });
});

test("rejected promises fail", async () => {
  const report = await runTests([{ name: "r", fn: async () => { throw new Error("async boom"); } }]);
  checkEq(report.results[0].error, "async boom");
});

test("thrown values that are not errors", async () => {
  const report = await runTests([{ name: "s", fn: () => { throw "plain"; } }]);
  checkEq(report.results[0].error, "plain");
});

test("slow tests time out and the rest still run", async () => {
  const report = await runTests([
    { name: "slow", fn: () => new Promise(() => {}) },
    { name: "after", fn: () => {} },
  ]);
  checkEq(report.results, [{ name: "slow", ok: false, error: "timed out" }, { name: "after", ok: true }]);
});

